"use client";

import { useCart } from "@/app/store/cart";
import { useState } from "react";
import CartModal from "./CartModal";
import { ChevronRight, ShoppingBasket } from "lucide-react";

export default function CartBar() {
  const items = useCart((s) => s.items);
  const [open, setOpen] = useState(false);
  const [isAnimating, setIsAnimating] = useState(false);

  if (items.length === 0) return null;

  const total = items.reduce((sum, i) => sum + i.price * i.qty, 0);
  const itemCount = items.reduce((sum, i) => sum + i.qty, 0);

  const handleClick = () => {
    setIsAnimating(true);
    setTimeout(() => setIsAnimating(false), 300);
    setOpen(true);
  };

  return (
    <>
      <div
        className="fixed bottom-0 left-0 right-0 z-30 p-4 cursor-pointer"
        onClick={handleClick}
      >
        {/* Item count floating on top of basket */}
        <div className="absolute bottom-28 right-8 z-40">
          <div className={`relative ${isAnimating ? 'animate-bounce' : ''}`}>
            <div className="w-14 h-14 bg-gradient-to-br from-emerald-500 to-emerald-600 rounded-full flex items-center justify-center shadow-2xl shadow-emerald-500/40">
              <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center">
                <span className="text-lg font-bold text-emerald-600">
                  {itemCount}
                </span>
              </div>
            </div>
            {/* Connecting line to basket */}
            <div className="absolute top-full left-1/2 transform -translate-x-1/2 w-1 h-8 bg-gradient-to-b from-emerald-500 to-transparent" />
          </div>
        </div>

        {/* Glow effect */}
        <div className="absolute inset-0 bg-gradient-to-r from-emerald-500/20 to-emerald-600/20 blur-xl opacity-50" />
        
        {/* Cart Bar with restaurant basket */}
        <div className="relative bg-gradient-to-r from-emerald-500 to-emerald-600 rounded-2xl p-4 shadow-2xl shadow-emerald-500/30 hover:shadow-emerald-500/40 transition-all duration-300 hover:scale-[1.02] active:scale-[0.98]">
          <div className="flex items-center justify-between">
            {/* Left side - Basket icon */}
            <div className="flex items-center gap-3">
              <div className="relative">
                {/* Restaurant serving basket */}
                <div className="w-14 h-14 bg-gradient-to-br from-amber-100 to-amber-50 rounded-xl flex items-center justify-center shadow-inner border border-amber-200">
                  <ShoppingBasket className="w-7 h-7 text-amber-700" />
                  
                  {/* Basket handle */}
                  <div className="absolute -top-1 left-1/2 transform -translate-x-1/2 w-10 h-3 border-t-4 border-amber-300 rounded-t-full" />
                  
                  {/* Basket weave pattern */}
                  <div className="absolute top-2 left-2 right-2 h-0.5 bg-amber-200/50" />
                  <div className="absolute top-4 left-2 right-2 h-0.5 bg-amber-200/50" />
                  <div className="absolute top-6 left-2 right-2 h-0.5 bg-amber-200/50" />
                  <div className="absolute left-2 top-2 bottom-2 w-0.5 bg-amber-200/50" />
                  <div className="absolute left-4 top-2 bottom-2 w-0.5 bg-amber-200/50" />
                  <div className="absolute left-6 top-2 bottom-2 w-0.5 bg-amber-200/50" />
                  <div className="absolute left-8 top-2 bottom-2 w-0.5 bg-amber-200/50" />
                </div>
              </div>
              
              <div className="text-white">
                <p className="text-sm font-medium opacity-90">Your Order Basket</p>
                <p className="text-xs opacity-75">
                  Ready to serve • {items.length} {items.length === 1 ? 'type' : 'types'}
                </p>
              </div>
            </div>

            {/* Right side - Total and arrow */}
            <div className="flex items-center gap-3">
              <div className="text-right">
                <p className="text-lg font-bold text-white">
                  ₹{total}
                </p>
                <p className="text-xs text-white/80">Total to pay</p>
              </div>
              
              <div className="w-10 h-10 bg-white/20 backdrop-blur-sm rounded-xl flex items-center justify-center">
                <ChevronRight className="w-5 h-5 text-white" />
              </div>
            </div>
          </div>
          
          {/* Order status indicator */}
          <div className="mt-3">
            <div className="flex items-center justify-between mb-1">
              <span className="text-xs text-white/80">Order Status</span>
              <span className="text-xs font-medium text-white">
                {itemCount < 5 ? '🟡 Adding items' : itemCount < 10 ? '🟢 Ready to order' : '🎉 Perfect order!'}
              </span>
            </div>
            <div className="h-2 bg-white/20 rounded-full overflow-hidden">
              <div 
                className="h-full bg-gradient-to-r from-amber-400 to-emerald-400 rounded-full transition-all duration-700"
                style={{ 
                  width: `${Math.min((itemCount / 15) * 100, 100)}%` 
                }}
              />
            </div>
          </div>
        </div>
        
        {/* Bottom safe area spacer */}
        <div className="h-4" />
      </div>

      {open && <CartModal onClose={() => setOpen(false)} />}
    </>
  );
}