import { create } from "zustand";

type CartItem = {
  productId: number;
  name: string;
  sizeLabel: string;
  price: number;
  qty: number;
  veg: boolean;
};

type CartStore = {
  items: CartItem[];
  addItem: (item: CartItem) => void;
  removeItem: (productId: number, sizeLabel: string) => void;
  updateQuantity: (productId: number, sizeLabel: string, newQty: number) => void;
  clearCart: () => void;
};

export const useCart = create<CartStore>((set) => ({
  items: [],

  addItem: (item) =>
    set((state) => {
      const existing = state.items.find(
        (i) =>
          i.productId === item.productId &&
          i.sizeLabel === item.sizeLabel
      );

      if (existing) {
  return {
    items: state.items.map((i) =>
      i === existing
        ? { ...i, qty: i.qty + item.qty }
        : i
    ),
  };
}

      return { items: [...state.items, item] };
    }),

  removeItem: (productId, sizeLabel) =>
    set((state) => ({
      items: state.items.filter(
        (i) =>
          !(i.productId === productId && i.sizeLabel === sizeLabel)
      ),
    })),

  updateQuantity: (productId, sizeLabel, newQty) =>
    set((state) => {
      // If quantity is 0 or less, remove the item
      if (newQty <= 0) {
        return {
          items: state.items.filter(
            (i) =>
              !(i.productId === productId && i.sizeLabel === sizeLabel)
          ),
        };
      }
      
      // Otherwise update the quantity
      return {
        items: state.items.map((item) =>
          item.productId === productId && item.sizeLabel === sizeLabel
            ? { ...item, qty: newQty }
            : item
        ),
      };
    }),

  clearCart: () => set({ items: [] }),
}));