"use client";

import { useCart } from "@/app/store/cart";
import { X, Trash2, ShoppingBag, Plus, Minus, Info } from "lucide-react";

export default function CartModal({ onClose }: { onClose: () => void }) {
  const { items, clearCart, updateQuantity, removeItem } = useCart();

  const total = items.reduce((sum, i) => sum + i.price * i.qty, 0);

  const handleIncrement = (productId: number, sizeLabel: string) => {
    const item = items.find(
      (i) => i.productId === productId && i.sizeLabel === sizeLabel
    );
    if (item) {
      updateQuantity(productId, sizeLabel, item.qty + 1);
    }
  };

  const handleDecrement = (productId: number, sizeLabel: string) => {
    const item = items.find(
      (i) => i.productId === productId && i.sizeLabel === sizeLabel
    );
    if (item) {
      if (item.qty > 1) {
        updateQuantity(productId, sizeLabel, item.qty - 1);
      } else {
        // Remove item when quantity reaches 0
        updateQuantity(productId, sizeLabel, 0);
      }
    }
  };

  const handleRemoveItem = (productId: number, sizeLabel: string) => {
    removeItem(productId, sizeLabel);
  };

  return (
    <div className="fixed inset-0 z-50">
      {/* Backdrop with blur */}
      <div
        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
        onClick={onClose}
      />

      {/* Cart Sheet */}
      <div className="absolute bottom-0 left-0 right-0 bg-white rounded-t-3xl shadow-2xl max-h-[90vh] flex flex-col animate-slide-up">
        {/* Header */}
        <div className="sticky top-0 bg-white border-b border-gray-100 rounded-t-3xl p-6 pb-4 z-10">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-emerald-50 rounded-lg">
                <ShoppingBag className="w-5 h-5 text-emerald-600" />
              </div>
              <div>
                <h2 className="font-bold text-xl text-gray-900">Your Cart</h2>
                <p className="text-sm text-gray-500">
                  {items.length} {items.length === 1 ? "item" : "items"}
                </p>
              </div>
            </div>
            <button
              onClick={onClose}
              className="p-2 hover:bg-gray-100 rounded-full transition-colors"
              aria-label="Close cart"
            >
              <X className="w-5 h-5 text-gray-500" />
            </button>
          </div>
        </div>

        {/* Cart Items */}
        <div className="flex-1 overflow-y-auto px-6 py-4">
          {items.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 text-center">
              <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mb-4">
                <ShoppingBag className="w-8 h-8 text-gray-400" />
              </div>
              <p className="text-gray-900 font-medium text-lg mb-2">
                Your cart is empty
              </p>
              <p className="text-gray-500 text-sm">Add items to get started</p>
            </div>
          ) : (
            <div className="space-y-4">
              {items.map((item) => (
                <div
                  key={`${item.productId}-${item.sizeLabel}`}
                  className="flex gap-4 p-4 rounded-2xl bg-gray-50 border border-gray-100 group relative"
                >
                  {/* Remove item button - appears on hover */}
                  <button
                    onClick={() => handleRemoveItem(item.productId, item.sizeLabel)}
                    className="absolute -top-2 -right-2 w-8 h-8 bg-rose-500 text-white rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity shadow-lg hover:bg-rose-600 z-20"
                    aria-label="Remove item"
                  >
                    <X className="w-4 h-4" />
                  </button>

                  {/* Veg/Non-veg indicator */}
                  <div className="flex-shrink-0">
                    <div
                      className={`w-6 h-6 rounded-full border-2 flex items-center justify-center ${
                        item.veg
                          ? "border-emerald-500 bg-emerald-50"
                          : "border-rose-500 bg-rose-50"
                      }`}
                    >
                      <div
                        className={`w-2 h-2 rounded-full ${
                          item.veg ? "bg-emerald-500" : "bg-rose-500"
                        }`}
                      />
                    </div>
                  </div>

                  {/* Item details */}
                  <div className="flex-1 min-w-0">
                    <div className="flex justify-between items-start mb-2">
                      <h3 className="font-semibold text-gray-900 pr-6">
                        {item.name}
                      </h3>
                      <p className="font-bold text-gray-900 ml-2">
                        ₹{item.price * item.qty}
                      </p>
                    </div>

                    {/* Size label and price per unit */}
                    <div className="flex items-center justify-between mb-3">
                      <span className="px-3 py-1 bg-white border border-gray-200 rounded-full text-sm text-gray-600">
                        {item.sizeLabel}
                      </span>
                      <span className="text-sm text-gray-600">
                        ₹{item.price} each
                      </span>
                    </div>

                    {/* Quantity controls and remove button */}
                    <div className="flex items-center justify-between">
                      <button
                        onClick={() => handleRemoveItem(item.productId, item.sizeLabel)}
                        className="flex items-center gap-1.5 text-rose-600 hover:text-rose-700 text-sm font-medium transition-colors"
                      >
                        <Trash2 className="w-4 h-4" />
                        Remove
                      </button>
                      
                      <div className="flex items-center gap-3">
                        <button
                          onClick={() =>
                            handleDecrement(item.productId, item.sizeLabel)
                          }
                          className={`w-8 h-8 rounded-full flex items-center justify-center ${
                            item.qty > 1
                              ? "bg-gray-100 text-gray-700 hover:bg-gray-200"
                              : "bg-gray-100 text-gray-400 cursor-not-allowed"
                          } transition-colors`}
                          disabled={item.qty <= 1}
                          aria-label="Decrease quantity"
                        >
                          <Minus className="w-4 h-4" />
                        </button>
                        
                        <span className="w-8 text-center font-semibold text-gray-900">
                          {item.qty}
                        </span>
                        
                        <button
                          onClick={() =>
                            handleIncrement(item.productId, item.sizeLabel)
                          }
                          className="w-8 h-8 rounded-full bg-emerald-50 text-emerald-700 flex items-center justify-center hover:bg-emerald-100 transition-colors"
                          aria-label="Increase quantity"
                        >
                          <Plus className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Footer */}
        {items.length > 0 && (
          <div className="sticky bottom-0 bg-white border-t border-gray-100 p-6 space-y-5">
            {/* Total */}
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-500">Total amount</p>
                <p className="text-2xl font-bold text-gray-900">₹{total}</p>
              </div>
              <div className="text-right">
                <p className="text-xs text-gray-500 mb-1">
                  Inclusive of all taxes
                </p>
                <div className="inline-flex items-center gap-1 px-3 py-1 bg-emerald-50 text-emerald-700 rounded-full text-sm">
                  <Info className="w-3 h-3" />
                  <span>Free delivery</span>
                </div>
              </div>
            </div>

            {/* Info Banner */}
            <div className="bg-blue-50 border border-blue-100 rounded-xl p-4">
              <div className="flex items-start gap-3">
                <Info className="w-5 h-5 text-blue-600 flex-shrink-0 mt-0.5" />
                <div>
                  <p className="text-sm font-medium text-blue-800 mb-1">
                    Show this cart to the waiter
                  </p>
                  <p className="text-xs text-blue-700">
                    Your order will be prepared once confirmed by the staff
                  </p>
                </div>
              </div>
            </div>

            {/* Clear Cart Button */}
            <button
              onClick={clearCart}
              className="w-full flex items-center justify-center gap-3 px-6 py-4 border-2 border-rose-100 bg-rose-50 text-rose-700 font-semibold rounded-xl hover:bg-rose-100 hover:border-rose-200 active:scale-[0.98] transition-all"
            >
              <Trash2 className="w-5 h-5" />
              Clear All Items
            </button>

            <p className="text-center text-xs text-gray-500 pt-2">
              You can modify quantities until the waiter confirms
            </p>
          </div>
        )}
      </div>
    </div>
  );
}